//! Binary blobs as Luau ModuleScripts. A Roblox script's source must stay
//! under 200k characters, so a blob is cut into chunk modules of at most
//! [`MAX_MODULE_CHARS`], each returning one `buffer`, plus an index module.
//! Every chunk carries its own small base64 decoder so it works wherever
//! assembly puts it. Layout: docs/formats/luau-blobs.md.

use std::path::{Path, PathBuf};

use base64::Engine;
use sha2::{Digest, Sha256};

pub const MAX_MODULE_CHARS: usize = 190_000;

const DECODER: &str = r#"--!native
-- Generated by oaconv. One chunk of a binary blob; see the index module.
local function decode(s: string): buffer
	local map = {}
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, 64 do
		map[string.byte(alphabet, i)] = i - 1
	end
	local n = #s
	local pad = 0
	if n > 0 and string.byte(s, n) == 61 then pad += 1 end
	if n > 1 and string.byte(s, n - 1) == 61 then pad += 1 end
	local len = n // 4 * 3 - pad
	local out = buffer.create(len)
	local o = 0
	for i = 1, n, 4 do
		local a, b, c, d = string.byte(s, i, i + 3)
		local v = map[a] * 262144 + map[b] * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
		buffer.writeu8(out, o, v // 65536)
		if o + 1 < len then buffer.writeu8(out, o + 1, (v // 256) % 256) end
		if o + 2 < len then buffer.writeu8(out, o + 2, v % 256) end
		o += 3
	end
	return out
end
"#;

/// Base64 characters per chunk: a multiple of 4 that leaves room for the decoder.
fn chunk_chars() -> usize {
    (MAX_MODULE_CHARS - DECODER.len() - 64) / 4 * 4
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// Writes `dir/<name>_000.luau`, ... and the index `dir/<name>.luau`.
/// Returns every file written, index last.
pub fn write_buffer_modules(dir: &Path, name: &str, bytes: &[u8]) -> std::io::Result<Vec<PathBuf>> {
    std::fs::create_dir_all(dir)?;
    let encoded = base64::engine::general_purpose::STANDARD.encode(bytes);
    let mut written = Vec::new();
    let mut chunk_names = Vec::new();
    let pieces: Vec<&str> = if encoded.is_empty() {
        vec![""]
    } else {
        encoded
            .as_bytes()
            .chunks(chunk_chars())
            .map(|c| std::str::from_utf8(c).unwrap())
            .collect()
    };
    for (i, piece) in pieces.iter().enumerate() {
        let chunk = format!("{name}_{i:03}");
        let path = dir.join(format!("{chunk}.luau"));
        std::fs::write(&path, format!("{DECODER}return decode(\"{piece}\")\n"))?;
        written.push(path);
        chunk_names.push(chunk);
    }
    let list: Vec<String> = chunk_names.iter().map(|c| format!("\"{c}\"")).collect();
    let index = format!(
        "-- Generated by oaconv. Require each chunk (sibling ModuleScripts) in order and\n\
         -- join them: the result is {} bytes, sha256 {}.\n\
         return {{ name = \"{name}\", size = {}, sha256 = \"{}\", chunks = {{ {} }} }}\n",
        bytes.len(),
        sha256_hex(bytes),
        bytes.len(),
        sha256_hex(bytes),
        list.join(", ")
    );
    let path = dir.join(format!("{name}.luau"));
    std::fs::write(&path, index)?;
    written.push(path);
    Ok(written)
}

/// Joins the chunks back the way the Luau side does, for tests.
pub fn read_buffer_modules(dir: &Path, name: &str) -> std::io::Result<Vec<u8>> {
    let mut out = Vec::new();
    for i in 0.. {
        let path = dir.join(format!("{name}_{i:03}.luau"));
        if !path.exists() {
            break;
        }
        let text = std::fs::read_to_string(path)?;
        let start = text
            .rfind("return decode(\"")
            .map(|p| p + 15)
            .ok_or(std::io::ErrorKind::InvalidData)?;
        let end = text[start..]
            .find('"')
            .ok_or(std::io::ErrorKind::InvalidData)?
            + start;
        out.extend(
            base64::engine::general_purpose::STANDARD
                .decode(&text[start..end])
                .map_err(std::io::Error::other)?,
        );
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn chunks_round_trip_and_stay_under_the_limit() {
        let dir = std::env::temp_dir().join(format!("oaconv-luau-{}", std::process::id()));
        let bytes: Vec<u8> = (0..400_000u32).map(|i| (i * 7 % 251) as u8).collect();
        let files = write_buffer_modules(&dir, "blob", &bytes).unwrap();
        assert_eq!(
            files.len(),
            4,
            "400k bytes = 533k base64 chars = 3 chunks + index"
        );
        for f in &files {
            assert!(std::fs::read_to_string(f).unwrap().len() < MAX_MODULE_CHARS);
        }
        assert_eq!(read_buffer_modules(&dir, "blob").unwrap(), bytes);
        std::fs::remove_dir_all(dir).unwrap();
    }
}
